import random
import time

TRANSIENT = {429, 502, 503, 504}

def wait_seconds(attempt, retry_after=None, base=1.0, cap=60.0):
    """Delay before the next attempt: Retry-After wins, else capped exponential backoff with jitter."""
    if retry_after is not None:
        return float(retry_after)
    return random.uniform(0, min(cap, base * 2 ** attempt))

for attempt in range(4):
    print(attempt, round(wait_seconds(attempt), 2), wait_seconds(attempt, retry_after=30))
